/* Hand-written guest functions for the hook engine tests (docs/hooks.md), written for these
 * tests. They are top-level assembly so that each patch window holds exactly the instructions
 * a test case needs; hook_guest_api.h gives each one's C signature and result. Functions with a
 * frame carry SEH directives, so they get .pdata and unwind info like compiled code. */

#include "hook_guest_api.h"

/* clang-format off */
__asm__(
    ".intel_syntax noprefix\n"

    ".data\n"
    ".p2align 2\n"
    "g6h_base: .long 100\n"

    ".text\n"

    /* A RIP-relative load as the first instruction: a moved copy must still reach g6h_base. */
    ".globl g6h_rip_prologue\n"
    ".def g6h_rip_prologue; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_rip_prologue:\n"
    "    mov eax, dword ptr [rip + g6h_base]\n"
    "    add eax, ecx\n"
    "    ret\n"

    /* A short conditional jump inside the first five bytes, to a target past them. */
    ".globl g6h_jcc_entry\n"
    ".def g6h_jcc_entry; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_jcc_entry:\n"
    "    test ecx, ecx\n"
    "    je 1f\n"
    "    lea eax, [rcx + rcx]\n"
    "    ret\n"
    "1:\n"
    "    mov eax, -1\n"
    "    ret\n"

    /* Shorter than a jump: a window here runs into the int3 padding after it. */
    ".globl g6h_tiny\n"
    ".def g6h_tiny; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_tiny:\n"
    "    xor eax, eax\n"
    "    ret\n"

    /* The loop jumps back to the second instruction, inside a window at the entry. */
    ".globl g6h_loop\n"
    ".def g6h_loop; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_loop:\n"
    "    xor eax, eax\n"
    "2:\n"
    "    inc eax\n"
    "    dec ecx\n"
    "    jnz 2b\n"
    "    ret\n"

    /* A call right after a four-byte prologue, inside a window at the entry. */
    ".globl g6h_calls\n"
    ".def g6h_calls; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_calls:\n"
    ".seh_proc g6h_calls\n"
    "    sub rsp, 40\n"
    ".seh_stackalloc 40\n"
    ".seh_endprologue\n"
    "    call g6h_jcc_entry\n"
    "    inc eax\n"
    "    add rsp, 40\n"
    "    ret\n"
    ".seh_endproc\n"

    /* A frame whose prologue is exactly five bytes: push rbx, then sub rsp, 32. */
    ".globl g6h_framed\n"
    ".def g6h_framed; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_framed:\n"
    ".seh_proc g6h_framed\n"
    "    push rbx\n"
    ".seh_pushreg rbx\n"
    "    sub rsp, 32\n"
    ".seh_stackalloc 32\n"
    ".seh_endprologue\n"
    "    mov ebx, edx\n"
    "    mov rax, rcx\n"
    "    mov ecx, edx\n"
    "    call rax\n"
    "    add eax, ebx\n"
    "g6h_site_epilogue:\n"
    "    add rsp, 32\n"
    "    pop rbx\n"
    "    ret\n"
    ".seh_endproc\n"

    ".globl g6h_mid_regs\n"
    ".def g6h_mid_regs; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_mid_regs:\n"
    "    mov rax, rcx\n"
    "g6h_site_regs:\n"
    "    add rax, rdx\n"
    "    imul rax, r8\n"
    "    add rax, r9\n"
    "    ret\n"

    /* The flags from the compare cross the hook site; the window doesn't change them. */
    ".globl g6h_mid_flags\n"
    ".def g6h_mid_flags; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_mid_flags:\n"
    "    cmp ecx, edx\n"
    "g6h_site_flags:\n"
    "    mov eax, 0\n"
    "    setl al\n"
    "    ret\n"

    ".globl g6h_mid_df\n"
    ".def g6h_mid_df; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_mid_df:\n"
    "    std\n"
    "g6h_site_df:\n"
    "    mov eax, 0\n"
    "    pushfq\n"
    "    pop rax\n"
    "    cld\n"
    "    ret\n"

    /* The code after the first ret runs only when a hook sends rip to it. */
    ".globl g6h_mid_redirect\n"
    ".def g6h_mid_redirect; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_mid_redirect:\n"
    "    mov eax, ecx\n"
    "g6h_site_redirect:\n"
    "    add eax, 1\n"
    "    add eax, 1\n"
    "    ret\n"
    "g6h_site_redirect_alt:\n"
    "    add eax, 1000\n"
    "    ret\n"

    /* Loads all sixteen vector registers, passes the hook site (a five-byte nop), and stores
     * them. xmm6 to xmm15 are saved and restored, as the calling convention requires. */
    ".globl g6h_mid_ymm\n"
    ".def g6h_mid_ymm; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_mid_ymm:\n"
    ".seh_proc g6h_mid_ymm\n"
    "    sub rsp, 168\n"
    ".seh_stackalloc 168\n"
    "    movaps xmmword ptr [rsp], xmm6\n"
    ".seh_savexmm xmm6, 0\n"
    "    movaps xmmword ptr [rsp + 16], xmm7\n"
    ".seh_savexmm xmm7, 16\n"
    "    movaps xmmword ptr [rsp + 32], xmm8\n"
    ".seh_savexmm xmm8, 32\n"
    "    movaps xmmword ptr [rsp + 48], xmm9\n"
    ".seh_savexmm xmm9, 48\n"
    "    movaps xmmword ptr [rsp + 64], xmm10\n"
    ".seh_savexmm xmm10, 64\n"
    "    movaps xmmword ptr [rsp + 80], xmm11\n"
    ".seh_savexmm xmm11, 80\n"
    "    movaps xmmword ptr [rsp + 96], xmm12\n"
    ".seh_savexmm xmm12, 96\n"
    "    movaps xmmword ptr [rsp + 112], xmm13\n"
    ".seh_savexmm xmm13, 112\n"
    "    movaps xmmword ptr [rsp + 128], xmm14\n"
    ".seh_savexmm xmm14, 128\n"
    "    movaps xmmword ptr [rsp + 144], xmm15\n"
    ".seh_savexmm xmm15, 144\n"
    ".seh_endprologue\n"
    "    vmovdqu ymm0, ymmword ptr [rcx]\n"
    "    vmovdqu ymm1, ymmword ptr [rcx + 32]\n"
    "    vmovdqu ymm2, ymmword ptr [rcx + 64]\n"
    "    vmovdqu ymm3, ymmword ptr [rcx + 96]\n"
    "    vmovdqu ymm4, ymmword ptr [rcx + 128]\n"
    "    vmovdqu ymm5, ymmword ptr [rcx + 160]\n"
    "    vmovdqu ymm6, ymmword ptr [rcx + 192]\n"
    "    vmovdqu ymm7, ymmword ptr [rcx + 224]\n"
    "    vmovdqu ymm8, ymmword ptr [rcx + 256]\n"
    "    vmovdqu ymm9, ymmword ptr [rcx + 288]\n"
    "    vmovdqu ymm10, ymmword ptr [rcx + 320]\n"
    "    vmovdqu ymm11, ymmword ptr [rcx + 352]\n"
    "    vmovdqu ymm12, ymmword ptr [rcx + 384]\n"
    "    vmovdqu ymm13, ymmword ptr [rcx + 416]\n"
    "    vmovdqu ymm14, ymmword ptr [rcx + 448]\n"
    "    vmovdqu ymm15, ymmword ptr [rcx + 480]\n"
    "g6h_site_ymm:\n"
    "    .byte 0x0f, 0x1f, 0x44, 0x00, 0x00\n"
    "    vmovdqu ymmword ptr [rdx], ymm0\n"
    "    vmovdqu ymmword ptr [rdx + 32], ymm1\n"
    "    vmovdqu ymmword ptr [rdx + 64], ymm2\n"
    "    vmovdqu ymmword ptr [rdx + 96], ymm3\n"
    "    vmovdqu ymmword ptr [rdx + 128], ymm4\n"
    "    vmovdqu ymmword ptr [rdx + 160], ymm5\n"
    "    vmovdqu ymmword ptr [rdx + 192], ymm6\n"
    "    vmovdqu ymmword ptr [rdx + 224], ymm7\n"
    "    vmovdqu ymmword ptr [rdx + 256], ymm8\n"
    "    vmovdqu ymmword ptr [rdx + 288], ymm9\n"
    "    vmovdqu ymmword ptr [rdx + 320], ymm10\n"
    "    vmovdqu ymmword ptr [rdx + 352], ymm11\n"
    "    vmovdqu ymmword ptr [rdx + 384], ymm12\n"
    "    vmovdqu ymmword ptr [rdx + 416], ymm13\n"
    "    vmovdqu ymmword ptr [rdx + 448], ymm14\n"
    "    vmovdqu ymmword ptr [rdx + 480], ymm15\n"
    "    vzeroupper\n"
    "    movaps xmm6, xmmword ptr [rsp]\n"
    "    movaps xmm7, xmmword ptr [rsp + 16]\n"
    "    movaps xmm8, xmmword ptr [rsp + 32]\n"
    "    movaps xmm9, xmmword ptr [rsp + 48]\n"
    "    movaps xmm10, xmmword ptr [rsp + 64]\n"
    "    movaps xmm11, xmmword ptr [rsp + 80]\n"
    "    movaps xmm12, xmmword ptr [rsp + 96]\n"
    "    movaps xmm13, xmmword ptr [rsp + 112]\n"
    "    movaps xmm14, xmmword ptr [rsp + 128]\n"
    "    movaps xmm15, xmmword ptr [rsp + 144]\n"
    "    add rsp, 168\n"
    "    ret\n"
    ".seh_endproc\n"

    /* A frame, and a hook site in the body that keeps rbx live across it. */
    ".globl g6h_mid_framed\n"
    ".def g6h_mid_framed; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_mid_framed:\n"
    ".seh_proc g6h_mid_framed\n"
    "    push rbx\n"
    ".seh_pushreg rbx\n"
    "    sub rsp, 32\n"
    ".seh_stackalloc 32\n"
    ".seh_endprologue\n"
    "    mov ebx, ecx\n"
    "g6h_site_framed:\n"
    "    lea ecx, [rbx + rbx*2]\n"
    "    mov eax, ecx\n"
    "    add rsp, 32\n"
    "    pop rbx\n"
    "    ret\n"
    ".seh_endproc\n"

    /* The load through the argument is in the window, so a fault happens in the moved copy. */
    ".globl g6h_mid_load\n"
    ".def g6h_mid_load; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_mid_load:\n"
    ".seh_proc g6h_mid_load\n"
    "    sub rsp, 40\n"
    ".seh_stackalloc 40\n"
    ".seh_endprologue\n"
    "g6h_site_load:\n"
    "    mov eax, dword ptr [rcx]\n"
    "    add eax, 1\n"
    "    add rsp, 40\n"
    "    ret\n"
    ".seh_endproc\n"

    /* A call followed by enough plain code that no other rule refuses a window at the call's
     * return address, or one an instruction later. */
    ".globl g6h_after_call\n"
    ".def g6h_after_call; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_after_call:\n"
    ".seh_proc g6h_after_call\n"
    "    sub rsp, 40\n"
    ".seh_stackalloc 40\n"
    ".seh_endprologue\n"
    "    call g6h_mid_framed\n"
    "g6h_site_return_address:\n"
    "    add eax, 1\n"
    "g6h_site_after_return:\n"
    "    add eax, 2\n"
    "    add eax, 4\n"
    "    add rsp, 40\n"
    "    ret\n"
    ".seh_endproc\n"

    /* A language handler that reads no tables and doesn't check the stack cookie: it leaves
     * every exception to the frames above (ExceptionContinueSearch). */
    ".p2align 4, 0xcc\n"
    "g6h_other_handler:\n"
    "    mov eax, 1\n"
    "    ret\n"

    /* A frame under that handler, which the engine can't check. Its handler data is a zero
     * count, so it doesn't read as a C scope table either. */
    ".globl g6h_handled\n"
    ".def g6h_handled; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_handled:\n"
    ".seh_proc g6h_handled\n"
    ".seh_handler g6h_other_handler, @except, @unwind\n"
    "    sub rsp, 40\n"
    ".seh_stackalloc 40\n"
    ".seh_endprologue\n"
    "    lea eax, [rcx + 5]\n"
    "    add rsp, 40\n"
    "    ret\n"
    ".seh_handlerdata\n"
    "    .long 0\n"
    ".text\n"
    ".seh_endproc\n"

    ".globl g6h_cpuid\n"
    ".def g6h_cpuid; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_cpuid:\n"
    ".seh_proc g6h_cpuid\n"
    "    push rbx\n"
    ".seh_pushreg rbx\n"
    ".seh_endprologue\n"
    "    mov r9, r8\n"
    "g6h_site_before_cpuid:\n"
    "    mov eax, ecx\n"
    "    mov ecx, edx\n"
    "    cpuid\n"
    "    mov dword ptr [r9], eax\n"
    "    mov dword ptr [r9 + 4], ebx\n"
    "    mov dword ptr [r9 + 8], ecx\n"
    "    mov dword ptr [r9 + 12], edx\n"
    "    pop rbx\n"
    "    ret\n"
    ".seh_endproc\n"

    /* After the ret: bytes that decode as cpuid and xgetbv but are never reached, so the trap
     * patching must leave them alone. */
    ".globl g6h_xgetbv\n"
    ".def g6h_xgetbv; .scl 2; .type 32; .endef\n"
    ".p2align 4, 0xcc\n"
    "g6h_xgetbv:\n"
    "    xgetbv\n"
    "    shl rdx, 32\n"
    "    or rax, rdx\n"
    "    ret\n"
    "g6h_site_lookalike:\n"
    "    .byte 0x0f, 0xa2, 0x0f, 0x01, 0xd0\n"

    /* In G6HSite order. */
    ".section .rdata,\"dr\"\n"
    ".p2align 2\n"
    ".globl g6h_sites\n"
    "g6h_sites:\n"
    "    .rva g6h_site_regs\n"
    "    .rva g6h_site_flags\n"
    "    .rva g6h_site_df\n"
    "    .rva g6h_site_redirect\n"
    "    .rva g6h_site_redirect_alt\n"
    "    .rva g6h_site_ymm\n"
    "    .rva g6h_site_framed\n"
    "    .rva g6h_site_load\n"
    "    .rva g6h_site_epilogue\n"
    "    .rva g6h_site_before_cpuid\n"
    "    .rva g6h_site_lookalike\n"
    "    .rva g6h_site_return_address\n"
    "    .rva g6h_site_after_return\n"

    ".text\n"
    ".att_syntax prefix\n");
/* clang-format on */
